(function(L,C){
  L.register('offline-threshold',(o={})=>{
    const a=o.values?.slice()||L.numbers(8,1,15),n=a.length,queries=o.queries||Array.from({length:4},()=>{const l=L.rand(0,n-1);return [l,L.rand(l,n-1),L.rand(1,15)];}),bit=Array(n+1).fill(0),answer=Array(queries.length).fill('—'),order=Array.from({length:n},(_,i)=>i).sort((i,j)=>a[i]-a[j]),ids=queries.map((_,i)=>i).sort((i,j)=>queries[i][2]-queries[j][2]),active=[];let p=0;
    const t=C.trace('offline-threshold',{values:a,queries},L.array(a)),s=(l,msg,v={},highlight=[])=>t.step(l,msg,{p,active,answer,...v},L.array(a,highlight,{pointers:p<n?{'order[p]':order[p]}:{},visited:active,aux:[{label:'树状数组（下标从 1 开始）',values:bit},{label:'原询问顺序的答案',values:answer}]}));
    s('init','询问为 [l,r,threshold]，统计闭区间内 ≤threshold 的数量。');s('sort','元素按数值、询问按阈值排序，但保留原编号。',{order,ids});s('pointer','指针 p 表示已经激活的元素数量。');for(const id of ids){const [l,r,threshold]=queries[id];s('loop','处理下一条阈值询问。',{id,l,r,threshold});while(p<n&&a[order[p]]<=threshold){s('activate','阈值相等的元素也必须在回答前加入。',{id,threshold,index:order[p]},[order[p]]);active.push(order[p]);for(let i=order[p]+1;i<=n;i+=i&-i){bit[i]++;s('add','沿 lowbit 更新包含当前位置的树状数组节点。',{i,id},[order[p]]);}p++;}const prefix=start=>{let result=0;for(let i=start;i>0;i-=i&-i){result+=bit[i];s('prefix','累加互不重叠的前缀块。',{i,count:result,id});}return result;};answer[id]=prefix(r+1)-prefix(l);s('query','区间计数 = 前缀(r+1) - 前缀(l)，答案放回原编号。',{id,l,r,threshold},Array.from({length:r-l+1},(_,i)=>l+i));}s('return','按原始询问顺序返回结果。');return t.done(answer);
  });
  L.register('mo-distinct',(o={})=>{
    const a=o.values?.slice()||L.numbers(9,1,5),n=a.length,queries=o.queries||Array.from({length:5},()=>{const l=L.rand(0,n-1);return [l,L.rand(l,n-1)];}),block=Math.max(1,Math.floor(Math.sqrt(n))),ids=queries.map((_,i)=>i).sort((i,j)=>{const x=Math.floor(queries[i][0]/block),y=Math.floor(queries[j][0]/block);return x!==y?x-y:(queries[i][1]-queries[j][1])*(x%2?-1:1);}),answer=Array(queries.length).fill('—'),count={};let left=0,right=-1,distinct=0;
    const t=C.trace('mo-distinct',{values:a,queries},L.array(a)),s=(l,msg,v={},active=[])=>t.step(l,msg,{left,right,distinct,frequency:count,answer,...v},L.array(a,active,{pointers:{left,right,...(Number.isInteger(v.i)?{i:v.i}:{})},range:[left,right],aux:[{label:'按原始询问顺序的答案',values:answer},{label:'当前窗口各数的频次',values:Object.entries(count).filter(([,n])=>n>0).map(([x,n])=>x+':'+n)}]}));
    const add=i=>{if(!count[a[i]])distinct++;count[a[i]]=(count[a[i]]||0)+1;s('add','加入一个数，频次从 0 变 1 时不同数增加。',{i},[i]);},remove=i=>{count[a[i]]--;if(count[a[i]]===0)distinct--;s('remove','移出一个数，频次降到 0 时不同数减少。',{i},[i]);};
    s('init','只处理静态闭区间询问，初始窗口 [0,-1] 为空。',{block});s('sort','先按左端点所在块排序，块内右端点交替升降。',{ids});for(const id of ids){const [l,r]=queries[id];s('loop','处理排序后的下一条询问。',{id,l,r});while(left>l){s('expandLeft','先扩大左边界。',{id,l,r});add(--left);}while(right<r){s('expandRight','扩大右边界。',{id,l,r});add(++right);}while(left<l){s('shrinkLeft','收缩左边界。',{id,l,r});const i=left++;remove(i);}while(right>r){s('shrinkRight','收缩右边界。',{id,l,r});const i=right--;remove(i);}answer[id]=distinct;s('answer','窗口与询问完全一致，保存当前不同数数量。',{id,l,r});}s('return','按原始编号返回全部答案。');return t.done(answer);
  });
})(AlgoLab,AlgoLab.competition);
